KG42.register("rules-92bf8040be13737e98692d57",{"id":"42-data_center_space_time_flexibility::v141-c-R005","paper":"42-data_center_space_time_flexibility","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Social-surplus clearing delivers allocations and prices under which consumer payments cover payments to suppliers and transmission providers, without financial gain to the ISO. Scope: Basic static social-surplus clearing with inflexible consumers, suppliers and transmission providers. Suppliers receive their connection-node price per unit of cleared injection, consumers pay their connection-node price per unit of cleared withdrawal, and transmission providers receive the absolute price difference between their supporting nodes as the unit remuneration. Scope: Basic static market; supplier injections, consumer withdrawals and transmission service. Condition: Payments apply to cleared quantities.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.social_welfare","settlement.payment"],"E":[{"edge_id":"v141-c-R005-E001","source":"clearing.social_welfare","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-e016","v141-b-g01-e024"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Basic static market; supplier injections, consumer withdrawals and transmission service. | Basic static social-surplus clearing with inflexible consumers, suppliers and transmission providers.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e016","v141-b-g01-e024","v141-b-g01-e027"]},"x":[{"variable_id":"x-v141-c-R005-p_i","symbol":"p_i","meaning":"Cleared power injection (load injected) of supplier i at its connection node n(i), used in supplier remuneration and in the revenue-adequacy identity.","kind":"operational","domain":"p_i \\ge 0 (cleared injection; source clearing also imposes p_i \\in [0,\\bar{p}_i])","unit":"power (e.g., MWh)","indices":["i \\in \\mathcal{S}"],"evidence_ids":["v141-b-g01-e008","v141-b-g01-e016","v141-b-g01-e027","v141-b-g01-e034"]},{"variable_id":"x-v141-c-R005-d_j","symbol":"d_j","meaning":"Cleared power withdrawal (load withdrawn) of consumer j at its connection node n(j), used in consumer charges and in the revenue-adequacy identity.","kind":"operational","domain":"d_j \\ge 0 (cleared withdrawal; source clearing also imposes d_j \\in [0,\\bar{d}_j])","unit":"power (e.g., MWh)","indices":["j \\in \\mathcal{D}"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e016","v141-b-g01-e027","v141-b-g01-e034"]},{"variable_id":"x-v141-c-R005-f_l","symbol":"f_l","meaning":"Cleared power flow on transmission line l, used in the transmission-provider unit remuneration and total payment expression.","kind":"operational","domain":"f_l \\in [-\\bar{f}_l,\\bar{f}_l] (source clearing domain)","unit":"power (e.g., MWh)","indices":["l \\in \\mathcal{L}"],"evidence_ids":["v141-b-g01-e012","v141-b-g01-e016","v141-b-g01-e027"]},{"variable_id":"x-v141-c-R005-f_k","symbol":"f_k","meaning":"Nonnegative cleared flow on directed edge k from line l(k) in the absolute-value reformulation; appears in the revenue-adequacy identity (2.12).","kind":"operational","domain":"f_k \\ge 0 (source directed-edge reformulation: f_{l^+}, f_{l^-} \\ge 0 and f_l=f_{l^+}-f_{l^-})","unit":"power (e.g., MWh)","indices":["k \\in \\mathcal{K}"],"evidence_ids":["v141-b-g01-e018","v141-b-g01-e022","v141-b-g01-e034"]},{"variable_id":"x-v141-c-R005-pi_n","symbol":"\\pi_n","meaning":"Cleared nodal price or LMP at node n, dual to the nodal power-balance constraint, used to charge consumers and remunerate suppliers and transmission providers.","kind":"operational","domain":"\\pi_n \\in \\mathbb{R}_+","unit":"currency per unit power (e.g., $/MWh)","indices":["n \\in \\mathcal{N}"],"evidence_ids":["v141-b-g01-e015","v141-b-g01-e017","v141-b-g01-e027","v141-b-g01-e034"]}],"theta":[],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"mathematical","role":"core","statement":"Social-surplus clearing delivers allocations and prices under which consumer payments cover payments to suppliers and transmission providers, without financial gain to the ISO. Scope: Basic static social-surplus clearing with inflexible consumers, suppliers and transmission providers.","expression":"\\sum_{j\\in\\mathcal{D}}\\pi_{n(j)}d_j = \\sum_{i\\in\\mathcal{S}}\\pi_{n(i)}p_i + \\sum_{k\\in\\mathcal{K}}(\\pi_{rec(k)}-\\pi_{snd(k)})f_k","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare","settlement.payment"],"variable_refs":["x-v141-c-R005-p_i","x-v141-c-R005-d_j","x-v141-c-R005-f_k","x-v141-c-R005-pi_n"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e016","v141-b-g01-e024","v141-b-g01-e034","v141-b-g01-e035"]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"core","statement":"Suppliers receive their connection-node price per unit of cleared injection, consumers pay their connection-node price per unit of cleared withdrawal, and transmission providers receive the absolute price difference between their supporting nodes as the unit remuneration. Scope: Basic static market; supplier injections, consumer withdrawals and transmission service. Condition: Payments apply to cleared quantities.","expression":"\\mathrm{pay}^{p}_{i}=\\pi_{n(i)}p_i\\quad(i\\in\\mathcal{S}),\\qquad \\mathrm{pay}^{d}_{j}=\\pi_{n(j)}d_j\\quad(j\\in\\mathcal{D}),\\qquad \\mathrm{pay}^{f}_{l}=|\\pi_{rec(l)}-\\pi_{snd(l)}|\\,|f_l|\\quad(l\\in\\mathcal{L})","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["x-v141-c-R005-p_i","x-v141-c-R005-d_j","x-v141-c-R005-f_l","x-v141-c-R005-pi_n"],"parameter_refs":[],"evidence_ids":["v141-b-g01-e027"]}],"pi":[{"evidence_id":"v141-b-g01-e016","location":{"location_id":"src-1c03246cb9-p03-c2r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"ic to be delivered at different locations); as such, a well-designed market a should properly remune","equation_id":"2.3","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"We begin our discussion by studying a clearing formulation with inflexible consumers: \\max_{d,p,f,\\theta} \\sum_{j\\in\\mathcal{D}}\\alpha^{d}_{j}d_{j}-\\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_{i}-\\sum_{l\\in\\mathcal{L}}\\alpha^{f}_{l}|f_{l}| \\quad (2.3a) s.t. \\sum_{l\\in\\mathcal{L}^{rec}_{n}} f_{l}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{l\\in\\mathcal{L}^{snd}_{n}}f_{l}+\\sum_{j\\in\\mathcal{D}_{n}}d_{j},\\quad (\\pi_n)\\ n\\in\\mathcal{N} \\quad (2.3b) f_{l}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L} \\quad (2.3c) d\\in C_{d},\\ p\\in C_{p},\\ \\theta\\in C_{\\theta} \\quad (2.3d). Here, we define the feasible capacity sets C_{d}:=\\{d| d_{j}\\in[0,\\bar{d}_{j}]\\ \\forall j\\in\\mathcal{D}\\}, C_{p}:=\\{p| p_{i}\\in[0,\\bar{p}_{i}]\\ \\forall i\\in\\mathcal{S}\\} and C_{\\theta}:=\\{\\theta| \\theta_{rec(l)}-\\theta_{snd(l)}\\in[-\\bar{\\Delta\\theta}_{l},\\bar{\\Delta\\theta}_{l}]\\ \\forall l\\in\\mathcal{L}\\}. The objective function (2.3a) is known as the social surplus or total welfare, which captures the value of demand served (to be maximized) and the cost of supply and transmission cost services (to be minimized). ... Constraint (2.3b) is the power balance constraint at each node n (Kirchhoff's current law)."},{"evidence_id":"v141-b-g01-e024","location":{"location_id":"src-1c03246cb9-p04-c1r4__v141-a-M01-settlement","page":4,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"p p y us • Revenue Adequacy: The clearing formulation delivers allocations and prices such that the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Revenue Adequacy: The clearing formulation delivers allocations and prices such that the total amount of money paid by service requesters (consumers) covers the total amount paid to all service providers (suppliers and transmission). This also ensures that the ISO does not have financial gain."},{"evidence_id":"v141-b-g01-e027","location":{"location_id":"src-1c03246cb9-p04-c2r2__v141-a-M01-pricing","page":4,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"for each unit of power cleared (withdrawn). Each transmission provider 4) 𝑙is remunerated using the ","equation_id":"2.8","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"We consider that each supplier i is remunerated with price \\pi_{n(i)} for each unit of power cleared (injected) and each consumer j pays \\pi_{n(j)} for each unit of power cleared (withdrawn). Each transmission provider l is remunerated using the unit price |\\pi_{rec(l)}-\\pi_{snd(l)}|, which is the price difference between the supporting nodes. The profit functions for supplier i\\in\\mathcal{S}, consumer j\\in\\mathcal{D}, and transmission provider l\\in\\mathcal{L} are thus: \\phi^{p}_{i}(\\pi_{n(i)},p_{i}) := (\\pi_{n(i)}-\\alpha^{p}_{i})p_{i} \\quad (2.8a) \\phi^{d}_{j}(\\pi_{n(j)},d_{j}) := (\\alpha^{d}_{j}-\\pi_{n(j)})d_{j} \\quad (2.8b) \\phi^{f}_{l}(\\pi_{rec(l)},\\pi_{snd(l)},f_{l}) := (|\\pi_{rec(l)}-\\pi_{snd(l)}|-\\alpha^{f}_{l})|f_{l}| \\quad (2.8c) When convenient, we use the short-hand notation \\phi^{p}_{i}, \\phi^{d}_{j}, and \\phi^{f}_{l}."},{"evidence_id":"v141-b-g01-e008","location":{"location_id":"src-1c03246cb9-p03-c1r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"We begin our discussion by introducing basic notation for a static to network (there is no time asso","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"Each supplier i \\in \\mathcal{S} is connected to the power grid at node n(i) \\in \\mathcal{N}. The supplier bids into the market by offering power at bid price \\alpha^{p}_{i} \\in \\mathbb{R}_{+} and offers available capacity \\bar{p}_{i} \\in [0,\\infty). We define \\mathcal{S}_{n} := \\{i \\in \\mathcal{S} | n(i)=n\\} \\subseteq \\mathcal{S} (set of suppliers connected to node n). The cleared allocation for supplier i \\in \\mathcal{S} (load injected) are denoted as p_i and must satisfy p_i \\in [0,\\bar{p}_{i}]. We use p to denote the collection of all cleared allocations."},{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-1c03246cb9-p03-c1r3__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"We begin our discussion by introducing basic notation for a static to network (there is no time asso","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"A consumer j \\in \\mathcal{D} bids into the market by requesting power at bid price \\alpha^{d}_{j} \\in \\mathbb{R}_{+} and requests a maximum capacity \\bar{d}_{j} \\in [0,\\infty). We define \\mathcal{D}_{n} := \\{j \\in \\mathcal{D} | n(j)=n\\} \\subseteq \\mathcal{D} (set of consumers connected to node n). For simplicity, we assume that there is only one consumer at a given node (\\mathcal{D}_{n} are singletons). The cleared allocation for consumer j \\in \\mathcal{D} (load withdrawn) is denoted as d_j and must satisfy d_j \\in [0,\\bar{d}_{j}]. We use d to denote the collection of all cleared allocations."},{"evidence_id":"v141-b-g01-e012","location":{"location_id":"src-1c03246cb9-p03-c2r1__v141-a-M01-bidding","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"Applied Energy 326 (2022) 119930 r- Each transmission owner has a line 𝑙∈defined by its sending a n","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"Each transmission owner has a line l \\in \\mathcal{L} defined by its sending node snd(l) \\in \\mathcal{N} and receiving node rec(l) \\in \\mathcal{N}. The definitions of snd(l) and rec(l) are interchangeable because power can flow in either direction. The sending and receiving nodes of a link are also known as its supporting nodes. For each node n \\in \\mathcal{N}, we define its set of receiving lines \\mathcal{L}^{rec}_{n} := \\{l \\in \\mathcal{L} | n=rec(l)\\} \\subseteq \\mathcal{L} and its set of sending lines \\mathcal{L}^{snd}_{n} := \\{l \\in \\mathcal{L} | n=snd(l)\\} \\subseteq \\mathcal{L}. Each line offers a bid price \\alpha^{f}_{l} \\in \\mathbb{R}_{+} and capacity \\bar{f}_{l} \\in [0,\\infty). Note that while in common market clearing practice, transmission line costs are not captured (i.e., \\alpha^{f}_{l}=0 for each line l), we add this generality in order to demonstrate the similarity between transmission network and flexibility network later. Each cleared flow f_l must satisfy the bounds f_l \\in [-\\bar{f}_{l},\\bar{f}_{l}] ..."},{"evidence_id":"v141-b-g01-e015","location":{"location_id":"src-1c03246cb9-p03-c2r2__v141-a-M01-pricing","page":3,"printed_page":null,"section":"2.1 Basic notation and terminology","anchor_text":"at collection 𝑓must obey the direct-current (DC) power flow equations: 4 𝑓𝑙= 𝐵𝑙(𝜃snd(𝑙) −𝜃rec(𝑙)), (","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"We use \\pi_n \\in \\mathbb{R}_{+} to represent the cleared price at node n \\in \\mathcal{N}. The collection of cleared prices is denoted as \\pi; these are also known as nodal prices or LMPs and are used to charge/remunerate market players. We observe that, in a typical market, suppliers and transmission owners offer a service to the grid, while inflexible consumers request a service from the grid. This distinction is important because we will see that flexible consumers (DaCes) act as prosumers that simultaneously request a service (request load) and offer a service (flexibility for load to be delivered at different locations); as such, a well-designed market should properly remunerate the provision of flexibility by DaCes."},{"evidence_id":"v141-b-g01-e017","location":{"location_id":"src-1c03246cb9-p03-c2r4__v141-a-M01-pricing","page":3,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"ng be maximized) and the cost of supply and transmission cost services is (to be minimized). The tra","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The solution of the market clearing problem gives the primal allocations (p,d,f) and the dual allocations \\pi. The dual allocations are the dual variables associated with the power balance constraints (2.3b). We will see that these can be used locational marginal prices (LMPs) that clear the market. We use (p,d,f,\\pi) to denote the primal-dual allocation obtained from the solution of the clearing formulation."},{"evidence_id":"v141-b-g01-e018","location":{"location_id":"src-1c03246cb9-p04-c1r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"W. Zhang and V.M. Zavala reformulated as a standard linear program by decomposing each line 𝑙 pr int","equation_id":"2.4","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"... reformulated as a standard linear program by decomposing each line l into directed edges l^{+}=(snd(l),rec(l)), l^{-}=(rec(l),snd(l)) and replace the terms in (2.3) as f_{l}\\leftarrow f_{l^{+}}-f_{l^{-}}, |f_{l}| \\leftarrow f_{l^{+}}+f_{l^{-}}, and f_{l^{+}}\\ge 0, f_{l^{-}}\\ge 0. We note that the validity of the absolute value reformulation relies on the assumption that the objective function is minimizing the absolute value, which helps reduce one of the (f_{l^{+}},f_{l^{-}}) to zero at the optimal solution ... We use \\mathcal{K} to represent the set of directed edges that results from this decomposition. Each edge k\\in\\mathcal{K} from line l(k)\\in\\mathcal{L} inherits the susceptance B_k:=B_{l(k)}, bid price \\alpha^{f}_{k}:=\\alpha^{f}_{l(k)}, and capacity \\bar{\\Delta\\theta}_{k}:=\\bar{\\Delta\\theta}_{l(k)}."},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-1c03246cb9-p04-c1r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"∑ ∑ ∑ min 𝛼𝑝𝑖𝑝𝑖+ 𝛼𝑓𝑘𝑓𝑘− 𝛼𝑑𝑗𝑑𝑗 (2.7a)𝑑,𝑝,𝑓,𝜃 𝑖∈ 𝑘∈ 𝑗∈ ∑ ∑ ∑ ∑ s.t. 𝑓𝑘+ 𝑝𝑖= 𝑓𝑘+ 𝑑𝑗, (𝜋𝑛) 𝑛∈ (2.7b)","equation_id":"2.7","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"This leads to the (equivalent) clearing problem: \\min_{d,p,f,\\theta} \\sum_{i\\in\\mathcal{S}}\\alpha^{p}_{i}p_{i}+\\sum_{k\\in\\mathcal{K}}\\alpha^{f}_{k}f_{k}-\\sum_{j\\in\\mathcal{D}}\\alpha^{d}_{j}d_{j} \\quad (2.7a) s.t. \\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}=\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}+\\sum_{j\\in\\mathcal{D}_{n}}d_{j},\\quad (\\pi_n)\\ n\\in\\mathcal{N} \\quad (2.7b) f_{l^{+}}-f_{l^{-}}=B_{l}(\\theta_{snd(l)}-\\theta_{rec(l)}),\\quad l\\in\\mathcal{L} \\quad (2.7c) d\\in C_{d},\\ p\\in C_{p},\\ \\theta\\in C_{\\theta} \\quad (2.7d). In this formulation, we minimize the negative surplus (as opposed to maximize the surplus); this equivalent representation will facilitate the analysis."},{"evidence_id":"v141-b-g01-e034","location":{"location_id":"src-1c03246cb9-p05-c1r2__v141-a-M01-settlement","page":5,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"Fig. 2. Standard market clearing mech we have that a solution of the Lagrangian dual problem also so","equation_id":"2.12","figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"To establish revenue adequacy, we need to show that the total revenue collected from consumers matches the total revenue allocated to service providers: \\sum_{j\\in\\mathcal{D}}\\pi_{n(j)}d_{j} = \\sum_{i\\in\\mathcal{S}}\\pi_{n(i)}p_{i}+\\sum_{k\\in\\mathcal{K}}(\\pi_{rec(k)}-\\pi_{snd(k)})f_{k}. \\quad (2.12)"},{"evidence_id":"v141-b-g01-e035","location":{"location_id":"src-1c03246cb9-p05-c1r3__v141-a-M01-settlement","page":5,"printed_page":null,"section":"2.2 Basic formulation with inflexible consumers","anchor_text":"∑ ∑ ∑ 𝜋𝑛(𝑗)𝑑𝑗= 𝜋𝑛(𝑖)𝑝𝑖+ (𝜋rec(𝑘) −𝜋snd(𝑘))𝑓𝑘. (2.12) U 𝑗∈ 𝑖∈ 𝑘∈ re From the power balance constra","equation_id":"2.13","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"From the power balance constraints (2.7b) we have that: \\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}-\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}-\\sum_{j\\in\\mathcal{D}_{n}}d_{j}=0. \\quad (2.13) This implies that, \\sum_{n\\in\\mathcal{N}}\\pi_n\\left(\\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}+\\sum_{i\\in\\mathcal{S}_{n}}p_{i}-\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}-\\sum_{j\\in\\mathcal{D}_{n}}d_{j}\\right)=0. \\quad (2.14) This expression can be written in the following equivalent form: \\sum_{j\\in\\mathcal{D}}\\pi_{n(j)}d_{j} = \\sum_{i\\in\\mathcal{S}}\\pi_{n(i)}p_{i}+\\sum_{n\\in\\mathcal{N}}\\pi_n\\left(\\sum_{k\\in\\mathcal{K}^{rec}_{n}}f_{k}-\\sum_{k\\in\\mathcal{K}^{snd}_{n}}f_{k}\\right) = \\sum_{i\\in\\mathcal{S}}\\pi_{n(i)}p_{i}+\\sum_{k\\in\\mathcal{K}}(\\pi_{rec(k)}-\\pi_{snd(k)})f_{k}, \\quad (2.15) which establishes revenue adequacy."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":"No fixed numeric parameter is used in the payment-rate and revenue-adequacy identities. Bid prices and capacities belong to bidding/clearing domains and are not part of this rule's stated settlement formulas."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-pricing","v141-a-M01-settlement"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e016","quote":"The objective function (2.3a) is known as the social surplus or total welfare, which captures the value of demand served (to be maximized) and the cost of supply and transmission cost services (to be minimized)."},{"evidence_id":"v141-b-g01-e024","quote":"The clearing formulation delivers allocations and prices such that the total amount of money paid by service requesters (consumers) covers the total amount paid to all service providers (suppliers and transmission). This also ensures that the ISO does not have financial gain."}],[{"evidence_id":"v141-b-g01-e027","quote":"We consider that each supplier i is remunerated with price \\pi_{n(i)} for each unit of power cleared (injected) and each consumer j pays \\pi_{n(j)} for each unit of power cleared (withdrawn). Each transmission provider l is remunerated using the unit price |\\pi_{rec(l)}-\\pi_{snd(l)}|, which is the price difference between the supporting nodes."}]],"C2_formalization":{"graph_sha256":"7bd6f01498ea867415b6d808ca80998a2794aabb30a1b0a0d37082f5091599ea","applicability":"formalized","reason":"Both core statements have explicit source formulas: C001 is formalized by the revenue-adequacy identity (2.12)/(2.15), and C002 by the settlement-rate/payment formulas in (2.8). The supplied B evidence remains unreviewed under the experiment policy; no independent source audit is claimed.","bindings":[{"object_id":"x-v141-c-R005-p_i","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"Supplier cleared injection p_i is produced by social-surplus clearing and is the quantity multiplied by \\pi_{n(i)} in the settlement payment expression; the frozen edge E001 links clearing to settlement."},{"object_id":"x-v141-c-R005-d_j","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"Consumer cleared withdrawal d_j is produced by social-surplus clearing and is the quantity multiplied by \\pi_{n(j)} in the settlement charge expression; E001 links clearing to settlement."},{"object_id":"x-v141-c-R005-f_l","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"Line flow f_l is a cleared flow from the social-surplus formulation and is the quantity multiplied by the absolute supporting-node price difference in transmission remuneration."},{"object_id":"x-v141-c-R005-f_k","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"Directed-edge flow f_k is part of the equivalent clearing representation and appears in the revenue-adequacy identity connecting clearing allocations and prices to settlement coverage."},{"object_id":"x-v141-c-R005-pi_n","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"Nodal price \\pi_n is the clearing dual price and the settlement rate used for supplier remuneration and consumer charges; E001 represents the clearing-to-settlement link."},{"object_id":"v141-c-R005-C001","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"The revenue-adequacy identity connects social-surplus clearing allocations and prices to aggregate settlement coverage; E001 is the frozen clearing-to-settlement edge for this rule."},{"object_id":"v141-c-R005-C002","node_ids":["settlement.payment"],"edge_ids":["v141-c-R005-E001"],"rationale":"The payment-rate formulas are settlement objects attached to settlement.payment; their cleared quantities and prices come from social-surplus clearing through E001."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"95d0eebd2ab53f2c184c842b669f456e95c07346c46b37bae21b6e775e5c204e","delivery_payload_sha256":"625cbfe624982dbcb6a2b67b7bfb113f4671cfeddb9054563774b56373ee7054","changes":[{"path":"graph_sha256","before":"7bd6f01498ea867b6d808ca80998a2794aabb30a1b0a0d37082f5091599ea","after":"7bd6f01498ea867415b6d808ca80998a2794aabb30a1b0a0d37082f5091599ea","reason":"Truncated metadata echo; exact saved input graph is authoritative."}],"scientific_fields_unchanged":true,"request_graph_sha256":"7bd6f01498ea867415b6d808ca80998a2794aabb30a1b0a0d37082f5091599ea","scientific_correctness_verified":false}},"quarantined_references":[]}});
